import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Ελλιπείς τιμές και διαφορές τιμολόγησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/pricing-problems.md","filePath":"el/help/pricing-problems.md"}'),o={name:"el/help/pricing-problems.md"};function i(s,a,n,p,c,h){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="ελλιπεις-τιμες-και-διαφορες-τιμολογησης" tabindex="-1">Ελλιπείς τιμές και διαφορές τιμολόγησης <a class="header-anchor" href="#ελλιπεις-τιμες-και-διαφορες-τιμολογησης" aria-label="Permalink to &quot;Ελλιπείς τιμές και διαφορές τιμολόγησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="γιατι-απαιτειται-χειροκινητη-προσφορα" tabindex="-1">Γιατί απαιτείται χειροκίνητη προσφορά; <a class="header-anchor" href="#γιατι-απαιτειται-χειροκινητη-προσφορα" aria-label="Permalink to &quot;Γιατί απαιτείται χειροκίνητη προσφορά;&quot;">​</a></h2><p>Ενδέχεται να μην υπάρχει κατάλληλη καταχωρισμένη τιμή για τη διαδρομή ή την υπηρεσία. Η προσωρινή μηδενική τιμή δεν σημαίνει δωρεάν μεταφορά. Οι εκκρεμείς προσφορές δεν επιβεβαιώνονται ούτε ανατίθενται πριν την έγκριση.</p><h2 id="γιατι-αλλαξε-το-συνολο" tabindex="-1">Γιατί άλλαξε το σύνολο; <a class="header-anchor" href="#γιατι-αλλαξε-το-συνολο" aria-label="Permalink to &quot;Γιατί άλλαξε το σύνολο;&quot;">​</a></h2><p>Συγκρίνετε διαδρομή, υπηρεσία, κατηγορία οχήματος, ημερομηνία και ώρα, πρόσθετες υπηρεσίες, εκπτώσεις επιστροφής και ρυθμισμένες εποχικές, εορταστικές ή νυχτερινές προσαυξήσεις. Ελέγξτε τον εφαρμοστέο φόρο και την επαληθευμένη ανάλυση. Συγκρίνετε ίδια στοιχεία αντί να αντιγράφετε παλαιά τιμή.</p><h2 id="τι-πρεπει-να-κανω" tabindex="-1">Τι πρέπει να κάνω; <a class="header-anchor" href="#τι-πρεπει-να-κανω" aria-label="Permalink to &quot;Τι πρέπει να κάνω;&quot;">​</a></h2><p>Χρησιμοποιήστε την τρέχουσα προσφορά και ζητήστε από εξουσιοδοτημένο διαχειριστή να επιλύσει ελλιπείς τιμές. Μην επινοείτε τιμές. Αν απορριφθεί παρωχημένη προσφορά, ανανεώστε την μέσω της εφαρμογής.</p><h2 id="αναφορα-προβληματος" tabindex="-1">Αναφορά προβλήματος <a class="header-anchor" href="#αναφορα-προβληματος" aria-label="Permalink to &quot;Αναφορά προβλήματος&quot;">​</a></h2><p>Δώστε τύπο υπηρεσίας, διαφορές στοιχείων χωρίς ευαίσθητα δεδομένα, έκδοση και μήνυμα σφάλματος. Μην περιλαμβάνετε στοιχεία επικοινωνίας επιβατών.</p><p>Δείτε <a href="/el/plus/pricing.html">Τιμολόγηση</a> και <a href="/el/plus/manual-quotations.html">Χειροκίνητες προσφορές</a>.</p>',11)])])}const u=e(o,[["render",i]]);export{m as __pageData,u as default};
